class SpacedRepetition{constructor(){this.QUALITY={DIFFICILE: 1,MOYEN: 3,FACILE: 5};this.MIN_INTERVAL=1;this.DEFAULT_EASINESS=2.5;}calculateNextReview(progress,difficulty){const now=new Date();const qualityMap={'difficile': this.QUALITY.DIFFICILE,'moyen': this.QUALITY.MOYEN,'facile': this.QUALITY.FACILE};const quality=qualityMap[difficulty.toLowerCase()]||this.QUALITY.MOYEN;if(!progress||!progress.repetitions){return this.initializeProgress(quality);}let easinessFactor=progress.easinessFactor||this.DEFAULT_EASINESS;let repetitions=progress.repetitions||0;let intervalDays=progress.intervalDays||0;const newEasiness=Math.max(1.3,easinessFactor+(0.1-(5-quality)*(0.08+(5-quality)*0.02)));let newRepetitions;let newInterval;if(quality<3){newRepetitions=0;newInterval=1;}else{newRepetitions=repetitions+1;if(newRepetitions===1){newInterval=1;}else if(newRepetitions===2){newInterval=6;}else{newInterval=Math.round(intervalDays*newEasiness);}}const nextReviewDate=new Date(now);nextReviewDate.setDate(nextReviewDate.getDate()+newInterval);return{easinessFactor: newEasiness,repetitions: newRepetitions,intervalDays: newInterval,lastReviewed: now,nextReview: nextReviewDate,lastDifficulty: difficulty,reviewCount:(progress.reviewCount||0)+1,difficultyHistory:{difficile:(progress.difficultyHistory?.difficile||0)+(difficulty==='difficile' ? 1 : 0),moyen:(progress.difficultyHistory?.moyen||0)+(difficulty==='moyen' ? 1 : 0),facile:(progress.difficultyHistory?.facile||0)+(difficulty==='facile' ? 1 : 0)}};}initializeProgress(quality){const now=new Date();const nextReview=new Date(now);let intervalDays;let difficulty;if(quality>=5){intervalDays=6;difficulty='facile';}else if(quality>=3){intervalDays=3;difficulty='moyen';}else{intervalDays=1;difficulty='difficile';}nextReview.setDate(nextReview.getDate()+intervalDays);return{easinessFactor: this.DEFAULT_EASINESS,repetitions: 1,intervalDays: intervalDays,lastReviewed: now,nextReview: nextReview,lastDifficulty: difficulty,reviewCount: 1,difficultyHistory:{difficile: difficulty==='difficile' ? 1 : 0,moyen: difficulty==='moyen' ? 1 : 0,facile: difficulty==='facile' ? 1 : 0}};}isDue(progress){if(!progress||!progress.nextReview){return true;}const now=new Date();return progress.nextReview<=now;}getPriorityScore(progress){if(!progress||!progress.repetitions){return 1000;}const now=new Date();const nextReview=progress.nextReview||now;const daysOverdue=Math.floor((now-nextReview)/(1000*60*60*24));const diffHistory=progress.difficultyHistory||{difficile: 0,moyen: 0,facile: 0};const total=diffHistory.difficile+diffHistory.moyen+diffHistory.facile;let difficultyScore=500;if(total>0){difficultyScore=(diffHistory.difficile*800+diffHistory.moyen*500+diffHistory.facile*200)/total;}const overdueBonus=Math.max(0,daysOverdue*50);return Math.min(1000,difficultyScore+overdueBonus);}sortByPriority(termsWithProgress){return termsWithProgress.sort((a,b)=>{const priorityA=this.getPriorityScore(a.progress);const priorityB=this.getPriorityScore(b.progress);return priorityB-priorityA;});}formatInterval(days){if(days===0)return "Aujourd'hui";if(days===1)return "Demain";if(days<7)return `Dans ${days}jours`;if(days<30){const weeks=Math.floor(days/7);return `Dans ${weeks}semaine${weeks>1 ? 's' : ''}`;}const months=Math.floor(days/30);return `Dans ${months}mois`;}getStatistics(allProgress){const stats={total: Object.keys(allProgress).length,neverReviewed: 0,dueToday: 0,mastered: 0,learning: 0,avgEasinessFactor: 0,difficultyDistribution:{difficile: 0,moyen: 0,facile: 0}};const now=new Date();let totalEF=0;let countEF=0;for(const progress of Object.values(allProgress)){if(!progress.repetitions){stats.neverReviewed++;}else{if(progress.nextReview&&progress.nextReview<=now){stats.dueToday++;}if(progress.intervalDays>=30){stats.mastered++;}else{stats.learning++;}if(progress.easinessFactor){totalEF+=progress.easinessFactor;countEF++;}if(progress.lastDifficulty){stats.difficultyDistribution[progress.lastDifficulty]++;}}}if(countEF>0){stats.avgEasinessFactor=(totalEF/countEF).toFixed(2);}return stats;}}if(typeof window!=='undefined'){window.SpacedRepetition=SpacedRepetition;}